  let a = (g - c) / (g + c);
  let b = (c * (g + c) - 1.0) / (c * (g - c) + 1.0);
  return select(0.5 * (a * a) * (b * b + 1.0), 1.0, g2 < 0.0);
}
fn waterPhaseHG(cosT: f32, g: f32) -> f32 {
  let g2 = g * g;
  return ((1.0 - g2) / (4.0 * PI)) / pow(max(1.0 + g2 - cosT * 2.0 * g, 1e-4), 1.5);
