fn waterDGGX(NdH: f32, a2: f32) -> f32 { let d = NdH * NdH * (a2 - 1.0) + 1.0; return a2 / (d * d * PI); }
fn waterVSmith(NdL: f32, NdV: f32, a2: f32) -> f32 {
  let gv = NdL * sqrt(NdV * NdV * (1.0 - a2) + a2);
